import React, { useEffect, useState, useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import PackageDetails from '../package-details';
import OrderTicket from '../order-ticket';
import DataService from '../../services/data-service';
import ConfigService from '../../services/config-service';
import ContractService from "../../services/esi-service";
import UtilsService from "../../services/utils-service";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faCopy } from '@fortawesome/free-regular-svg-icons';

function calculatePricing(inboundRouteDeep, price, volume, janice, rushFee = 0, applyRushFee = false) {
    const volumeIsk = inboundRouteDeep ? Math.ceil(volume * inboundRouteDeep.reward.volume) : 0;
    const collateralIsk = inboundRouteDeep ? Math.ceil((price / 100) * inboundRouteDeep.reward.collateral) : 0;
    const volumeInvalid = inboundRouteDeep ? inboundRouteDeep.limits.volume < volume : false;
    const collateralInvalid = inboundRouteDeep ? inboundRouteDeep.limits.collateral < price : false;
    let total = volumeIsk + collateralIsk;

    if (inboundRouteDeep && total < inboundRouteDeep.minimumReward) {
        total = inboundRouteDeep.minimumReward;
    }

    if (applyRushFee) {
        total += rushFee;
    }

    return {
        price: price,
        volume: volume,
        janice: janice,
        totals: {
            volumeInvalid: volumeInvalid,
            collateralInvalid: collateralInvalid,
            volume: volumeIsk,
            collateral: collateralIsk,
            rush: applyRushFee ? rushFee : 0,
            total: total
        }
    };
}

export default function ContractCreator() {
    const { t } = useTranslation();
    // API-loaded data
    const [data, setData] = useState(null);
    const [isLoaded, setIsLoaded] = useState(false);

    const [pricing, setPricing] = useState(calculatePricing(null, 0, 0, ""));
    const [outboundValue, setOutboundValue] = useState(""); // will be set after data load
    const [inboundValue, setInboundValue] = useState("");

    const [inboundRoute, setInboundRoute] = useState();
    const [outboundRoute, setOutboundRoute] = useState();

    const [rushOrderCheck, setRushOrderCheck] = useState(false);

    const [outstandingContracts, setOutstandingContracts] = useState();
    const [progressContracts, setProgressContracts] = useState();
    const [HundredContracts, setLast100ContractTime] = useState();
    const [MJJitaHundredContracts, setLast100MJJitaContracts] = useState();

    const [showInvalidDialog, setShowInvalidDialog] = useState(false);
    const [pricingCalculated, setPricingCalculated] = useState(false);

    const rushAllowed = inboundRoute?.allowRush === true;

    // Rush fee: override on route, else default from API data, else hardcoded fallback
    const rushFee = useMemo(() => {
        if (inboundRoute?.overrideRushFeeAmount != null) {
            return inboundRoute.overrideRushFeeAmount;
        }
        if (data?.default?.fees?.rushFeeAmount != null) {
            return data.default.fees.rushFeeAmount;
        }
        // Fallback if API default missing
        return 150000000;
    }, [inboundRoute, data]);

    const displayRushFee = rushFee;

    // Load data from API (routes + default)
    useEffect(() => {
        DataService.getData().then(content => {
            setData(content);
            if (content?.default?.region && content?.default?.system) {
                setOutboundValue(content.default.region + "|" + content.default.system);
            }
            setIsLoaded(true);
        });
    }, []);

    // Load contract stats
    useEffect(() => {
        ContractService.getContracts().then(r => {
            setOutstandingContracts(r.Outstanding);
            setProgressContracts(r.InProgress);
            setLast100ContractTime(r.HundredContracts);
            setLast100MJJitaContracts(r.MJJitaHundredContracts);
        }).catch(console.log);
    }, []);

    // Update outbound route when outboundValue or data changes
    useEffect(() => {
        if (!data || !outboundValue) return;
        setOutboundRoute(DataService.getOutboundRoute(data, outboundValue));
    }, [data, outboundValue]);

    // Update inbound route when inboundValue / outboundValue / data changes
    useEffect(() => {
        if (!data) return;
        setInboundRoute(DataService.getInboundRoute(data, outboundValue, inboundValue));
    }, [data, outboundValue, inboundValue]);

    // Recalculate pricing when route / inputs / rush info changes
    useEffect(() => {
        setPricing(calculatePricing(
            inboundRoute,
            pricing.price,
            pricing.volume,
            pricing.janice,
            rushFee,
            rushOrderCheck && rushAllowed
        ));
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [
        inboundRoute,
        pricing.price,
        pricing.volume,
        pricing.janice,
        rushFee,
        rushOrderCheck,
        rushAllowed
    ]);

    // Ensure rush checkbox is disabled/cleared when rush stops being allowed
    useEffect(() => {
        const rushStillAllowed = inboundRoute?.allowRush === true;
        const shouldApplyRush = rushOrderCheck && rushStillAllowed;

        if (!rushStillAllowed && rushOrderCheck) {
            setRushOrderCheck(false);
        }

        setPricing(calculatePricing(
            inboundRoute,
            pricing.price,
            pricing.volume,
            pricing.janice,
            rushFee,
            shouldApplyRush
        ));
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [
        outboundRoute,
        inboundRoute,
        pricing.price,
        pricing.volume,
        pricing.janice,
        rushFee,
        rushOrderCheck
    ]);

    const handleOutboundChanged = (event) => setOutboundValue(event.target.value);
    const handleInboundChanged = (event) => setInboundValue(event.target.value);

    const handlePricingChange = (price, volume, janice) => {
        setPricing(calculatePricing(
            inboundRoute,
            price,
            volume,
            janice,
            rushFee,
            rushOrderCheck && rushAllowed
        ));
        setPricingCalculated(true);
    };

    useEffect(() => {
        if (pricingCalculated && pricing.totals) {
            if (pricing.totals.volumeInvalid || pricing.totals.collateralInvalid) {
                setShowInvalidDialog(true);
            }
        }
    }, [pricing, pricingCalculated]);

    return (
        <>
            <div className="flex flex-wrap -mx-1 overflow-hidden sm:-mx-1 md:-mx-1 lg:-mx-1 xl:-mx-1">
            <div className="my-1 px-1 w-full overflow-hidden sm:my-1 sm:px-1 sm:w-1/2 md:my-1 md:px-1 md:w-1/2 lg:my-1 lg:px-1 lg:w-1/2 xl:my-1 xl:px-1 xl:w-1/2">
                <div className="shadow-lg rounded-lg bg-gray-900 border border-gray-700 px-4 py-3">
                    <div className="my-2 text-gray-300 text-sm">
                        <div className="bg-gray-900 text-white p-6 rounded-lg shadow-lg border border-gray-700">
                            <div className="headerCont text-center md:text-left">
                                <h4 className="uppercase tracking-widest text-sm text-gray-400 mb-1 md:block">{t('welcome.title')}</h4>
                                <h3 className="font-extrabold text-3xl md:text-4xl text-blue-400 md:block">{t('welcome.subtitle')}</h3>

                                <a
                                    className="inline-flex items-center mt-4 text-lg text-blue-500 hover:text-blue-300 focus:text-blue-300 transition-colors duration-200"
                                    href={ConfigService.discord_url}
                                    target="_blank"
                                    rel="noreferrer"
                                >
                                    <span className="uppercase font-medium tracking-wide">{t('nav.joinDiscord')}</span>
                                    <span className="text-xl ml-2 animate-pulse">&#x279c;</span>
                                </a>
                            </div>
                        </div>
                        <div className="max-w-5xl mx-auto p-4">
                            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">

                                {/* Box 1: Task Overview */}
                                <div className="bg-gray-900 border border-gray-700 rounded-lg p-6 text-center shadow-lg">
                                    <h2 className="text-sm uppercase text-gray-400 tracking-widest mb-2">{t('stats.taskStatus')}</h2>
                                    <p className="text-3xl font-extrabold text-green-400">{outstandingContracts}</p>
                                    <p className="text-xs text-gray-500 mt-1">{t('stats.outstanding')}</p>
                                    <p className="text-2xl font-bold text-yellow-400 mt-4">{progressContracts}</p>
                                    <p className="text-xs text-gray-500">{t('stats.inProgress')}</p>
                                </div>

                                {/* Box 2: Contract Time */}
                                <div className="bg-gray-900 border border-gray-700 rounded-lg p-6 text-center shadow-lg">
                                    <h2 className="text-sm uppercase text-gray-400 tracking-widest mb-2">{t('stats.avgContractTime')}</h2>
                                    <p className="text-4xl font-extrabold text-blue-400">{HundredContracts}h</p>
                                    <p className="text-xs text-gray-500 mt-1">{t('stats.hoursPerContract')}</p>
                                </div>

                                {/* Box 3: MJ to Jita */}
                                <div className="bg-gray-900 border border-gray-700 rounded-lg p-6 text-center shadow-lg">
                                    <h2 className="text-sm uppercase text-gray-400 tracking-widest mb-2">{t('stats.travelTime')}</h2>
                                    <p className="text-4xl font-extrabold text-purple-400">{MJJitaHundredContracts}h</p>
                                    <p className="text-xs text-gray-500 mt-1">{t('stats.journeyDuration')}</p>
                                </div>

                            </div>
                        </div>

                    </div>
                    <h2 className="w-full text-xl text-blue-400 font-bold uppercase tracking-wider mb-1">{t('contractCreator.title')}</h2>
                    <h3 className="w-full text-gray-400 font-medium text-sm mb-4">{t('contractCreator.subtitle')}</h3>

                    {/* Pickup */}
                    <div className="flex justify-between items-center text-sm text-gray-300 mb-2">
                        <label htmlFor="outbound" className="mr-2">{t('contractCreator.pickup')}</label>
                        <select
                            name="outbound"
                            value={outboundValue}
                            onChange={handleOutboundChanged}
                            className="bg-gray-800 border border-gray-600 text-gray-200 px-3 py-1 rounded w-2/3"
                        >
                            <option disabled hidden value=''></option>
                            {isLoaded && data
                                ? data.routes.map(route => (
                                    <optgroup key={route.region} label={route.region}>
                                        {route.systems.map(system => (
                                            <option
                                                key={`${route.region}-${system.system}`}
                                                value={route.region + "|" + system.system}
                                            >
                                                {system.system}
                                            </option>
                                        ))}
                                    </optgroup>
                                ))
                                : null}
                        </select>
                    </div>

                    {/* Station from */}
                    <div className="flex justify-between items-center my-2 border-b border-dashed border-blue-700 pb-1 text-sm text-gray-400">
                        <div>{t('contractCreator.stationFrom')}</div>
                        <div className="flex items-center space-x-2">
                            <span
                                className="cursor-pointer hover:text-white"
                                onClick={() => outboundRoute && UtilsService.clipboardCopy(outboundRoute.station)}
                            >
                                {outboundRoute && outboundRoute.station}
                            </span>
                            <FontAwesomeIcon
                                className="cursor-pointer text-blue-500 hover:text-blue-300"
                                icon={faCopy}
                                onClick={() => outboundRoute && UtilsService.clipboardCopy(outboundRoute.station)}
                            />
                        </div>
                    </div>

                    {/* Dropoff */}
                    <div className="flex justify-between items-center text-sm text-gray-300 mb-2">
                        <label htmlFor="inbound" className="mr-2">{t('contractCreator.dropoff')}</label>
                        <select
                            name="inbound"
                            value={inboundValue}
                            onChange={handleInboundChanged}
                            className="bg-gray-800 border border-gray-600 text-gray-200 px-3 py-1 rounded w-2/3"
                        >
                            <option value="">None</option>
                            {isLoaded && data
                                ? DataService.getRoutes(data, outboundValue).map(route => (
                                    <optgroup key={route.region} label={route.region}>
                                        {route.systems.map(system => (
                                            <option
                                                key={`${route.region}-${system.system}`}
                                                value={route.region + "|" + system.system}
                                            >
                                                {system.system}
                                            </option>
                                        ))}
                                    </optgroup>
                                ))
                                : null}
                        </select>
                    </div>

                    {/* Station to */}
                    <div className="flex justify-between items-center my-2 border-b border-dashed border-purple-700 pb-1 text-sm text-gray-400">
                        <div>{t('contractCreator.stationTo')}</div>
                        <div className="flex items-center space-x-2">
                            <span
                                className="cursor-pointer hover:text-white"
                                onClick={() => inboundRoute && UtilsService.clipboardCopy(inboundRoute.station)}
                            >
                                {inboundRoute && inboundRoute.station}
                            </span>
                            <FontAwesomeIcon
                                className="cursor-pointer text-purple-500 hover:text-purple-300"
                                icon={faCopy}
                                onClick={() => inboundRoute && UtilsService.clipboardCopy(inboundRoute.station)}
                            />
                        </div>
                    </div>

                    {/* Rush checkbox */}
                    <div className="mb-4 mt-3">
                        <label className="flex items-center text-sm text-gray-300">
                            <input
                                type="checkbox"
                                className="form-check-input appearance-none border border-gray-500 rounded-sm bg-gray-800 checked:bg-blue-600 checked:border-blue-600 focus:outline-none transition duration-200 mr-2 cursor-pointer"
                                checked={rushOrderCheck}
                                onChange={(e) => setRushOrderCheck(e.target.checked)}
                                disabled={!rushAllowed}
                                id="rushOrderTop"
                            />
                            <span className={`font-semibold ${!rushAllowed ? 'opacity-50 text-gray-500' : 'text-blue-400'}`}>
                                {t('contractCreator.rushDelivery')}
                            </span>
                        </label>
                        <div className={`text-xs mt-1 ml-6 leading-snug ${!rushAllowed ? 'text-gray-500' : 'text-gray-400'}`}>
                            +<span className="font-bold text-green-400">{displayRushFee.toLocaleString()}</span> {t('contractCreator.rushFee')} — <span className="font-semibold text-yellow-300">{t('contractCreator.guaranteedPriority')}</span><br />
                            <span className="italic text-gray-500">
                                {t('contractCreator.rushDescription')}
                            </span>
                        </div>
                    </div>

                    <PackageDetails system={inboundRoute} onPricingChange={handlePricingChange} />

                    <div className="bg-gray-800 border-l-4 border-blue-600 rounded-md text-blue-300 px-4 py-3 shadow-md mt-4" role="alert">
                        <div className="flex">
                            <div className="py-1">
                                <svg className="fill-current h-6 w-6 text-blue-500 mr-4" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20">
                                    <path d="M2.93 17.07A10 10 0 1 1 17.07 2.93 10 10 0 0 1 2.93 17.07zm12.73-1.41A8 8 0 1 0 4.34 4.34a8 8 0 0 0 11.32 11.32zM9 11V9h2v6H9v-4zm0-6h2v2H9V5z" />
                                </svg>
                            </div>
                            <div>
                                <p className="font-bold text-white">{t('contractCreator.informationalNotice')}</p>
                                <p className="text-sm">
                                    {t('contractCreator.contractsIssuedTo')}
                                </p>
                                <p>
                                    {t('contractCreator.note')}
                                </p>
                            </div>
                        </div>
                    </div>

                </div>
            </div>
            <div className="my-1 px-1 w-full overflow-hidden sm:w-1/2">
                <div className="flex justify-center w-full p-4">
                    <OrderTicket
                        outbound={outboundRoute}
                        inbound={inboundRoute}
                        pricing={pricing}
                        rushFee={rushOrderCheck && rushAllowed ? rushFee : 0}
                    />
                </div>
            </div>
        </div>

        {showInvalidDialog && (
            <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50">
                <div className="bg-gray-800 border border-red-500 rounded-lg shadow-2xl max-w-md w-full mx-4 p-6">
                    <div className="flex items-center justify-center mb-4">
                        <div className="bg-red-900 rounded-full p-3">
                            <svg className="w-8 h-8 text-red-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
                            </svg>
                        </div>
                    </div>
                    <h3 className="text-xl font-bold text-center text-red-500 mb-2">{t('dialog.packageTooLarge')}</h3>
                    <div className="mb-4">
                        {pricing.totals.volumeInvalid && (
                            <div className="bg-red-900 bg-opacity-30 border border-red-700 rounded p-3 mb-2">
                                <div className="text-red-400 font-semibold text-sm">{t('dialog.volumeExceedsLimit')}</div>
                                <div className="text-gray-300">
                                    {t('dialog.current')}: <span className="font-bold text-red-400">{Number(pricing.volume).toLocaleString()} m³</span> 
                                    {' / '}
                                    {t('dialog.max')}: <span className="font-bold text-green-400">{inboundRoute && Number(inboundRoute.limits.volume).toLocaleString()} m³</span>
                                </div>
                            </div>
                        )}
                        {pricing.totals.collateralInvalid && (
                            <div className="bg-red-900 bg-opacity-30 border border-red-700 rounded p-3">
                                <div className="text-red-400 font-semibold text-sm">{t('dialog.collateralExceedsLimit')}</div>
                                <div className="text-gray-300">
                                    {t('dialog.current')}: <span className="font-bold text-red-400">{Number(pricing.price).toLocaleString()} ISK</span>
                                    {' / '}
                                    {t('dialog.max')}: <span className="font-bold text-green-400">{inboundRoute && Number(inboundRoute.limits.collateral).toLocaleString()} ISK</span>
                                </div>
                            </div>
                        )}
                    </div>
                    <p className="text-gray-400 text-sm text-center mb-6">
                        {t('dialog.changePackageDetails')}
                    </p>
                    <div className="flex justify-center">
                        <button
                            onClick={() => setShowInvalidDialog(false)}
                            className="bg-red-600 hover:bg-red-500 text-white font-bold py-2 px-6 rounded transition duration-200"
                        >
                            {t('dialog.ok')}
                        </button>
                    </div>
                </div>
            </div>
        )}
        </>
    );
};
